#!/usr/bin/env python3
"""mado round 48 w2 FALSIFY — 32 concrete attacks on the frozen C1/C2 contracts and data, v1 policy 32-64."""
import collections
import json
import os

LANE = "/home/vgpnk/Projects/shokunin/mado-shokunin"
W = LANE + "/.ufo/waves/round-48"
SCR = "/fast/scratch/hyaku/mado-r48"
BASE = "579f694b45c797a9c39761fdb4f9e0a1b71b3585"
GODSPEED = "/skill:godspeed\n\nYou are a Godspeed-enabled subagent.\n\n1. **Name the axes.**\n2. **Iterate cheap, in parallel.**\n3. **Keep moves that improve any axis and harm none.**\n4. **Don't aim — let the frontier walk itself.**\n\n## IMMEDIATELY STOP ASKING CLARIFYING QUESTIONS. Execute tool calls concurrently in large batches. Do not serialize what can run in parallel. Do not output philosophical reasoning or verbose plans. Act directly via tool calls.\n\n"
CONTEXT = f"""# Goal
mado round 48, wave w2 = FALSIFY, policy v1, base {BASE}; lane {LANE}. This wave attacks the frozen registration and C1/C2 data before any data commit. W1 supplied >=32 concrete items: 204 warm fixtures, 20 C1 controls, 11 C2 source rows/pins/quotes, 9 numbered entry steps, 7 admitted/rejected candidate dispositions, and routed D1-D4/R3/R4b items. Claims and frozen predicates are in {W}/claims.md and {W}/registration.md; read those first. W2 cannot change the predicate, counters, fixture set, claims or target after scoring; if a defect breaks the frozen predicate, report it as a miss, never narrow it.

# Write scope / safety
- You are a leaf. Write only your own evidence in {W}/w2/<Seat>/ and your own report at {LANE}/.ufo/waves/round-48/w2/<Seat>.md. Every `Report:` trailer is relative to {LANE}; write it at {LANE}/<that path>. Never edit tracked lane files, registry, counters, entry, report, fleet repo, sibling lanes or shokuknow; the L1 integrates. No lane Git/jj mutation and no commit/push.
- Every clone, work tree, build, fixture and temp file lives under {SCR}/<Seat>/; create it explicitly, `trap 'rm -rf -- "$S"' EXIT`, copy receipts to your seat dir before deleting. Never use /tmp; every loop/write bounded to 2 GB total and 1 MB/file. The L1's /fast scratch is not your seat path.
- Before any shell writer command, run `ulimit -f 2048` (POSIX 512-byte units; 1 MiB per regular file) and record the largest output file. Use bounded loops; shell file-size limits are a guard, not a substitute for each seat's 2 GB total scratch budget and 1 MB/file cap.
- Tooling authorization: read /home/vgpnk/.omp/agent/RULES.md first; pacman transactions PAUSED host-wide—do not run pacman or any package transaction. No installation is needed for this wave unless justified and recorded.
- Host: no compositor/service mutation, no input injection, no GUI or terminal launch. `xdg-terminal-exec` ONLY with a --print-* option and XDG_CACHE_HOME inside your scratch; `xkbcli` only compile-keymap/test/kccgst read verbs. Host config and binaries are read-only. Never print or commit serials, window titles, process tables or home listings.
- Fixture repos must be `D=$(mktemp -d -p {SCR}/<Seat>) && git -C "$D" init -q`; every git call uses `-C "$D"`, verify the root equals D before any commit. No throwaway identity anywhere else.
- Commands start at fleet root; all paths are absolute. Evidence names the attack, command and observed output. Never write relative to `$PWD`.
"""
items=[]
def seat(name, role, target, task):
    items.append({"name":name,"role":role,"prompt":GODSPEED+"# Target\n"+target+"\n# Required shell writer bound\nStart each bash writer shell with `ulimit -f 2048` (512-byte units; 1 MiB per regular file); record the largest output file. Keep total scratch under 2 GB and clean it before return.\n# Task\n"+task+"\n"})
# 8 reviewers: claim/evidence and full independent replay attacks.
for n, target, task in [
("RevC1Counter", "Attack frozen C1 counter clauses a/s/f/w/x/g/i/r and its controls.", "Read the frozen C1 script and its docstring; test the actual lane counter on scratch clones against the frozen reference and at least one control each of trust-any, no-line-limit, delegate-ls, no-write, explain-cmd-const. Check whether every observed mutation trips the clause it claims, and whether a cheap variant reaches TARGET_MET. Report a table with exact commands, outputs and clause; any candidate false pass is a release blocker."),
("RevC1Cache", "Attack C1 cache contract semantics against the v0.14.3 pin.", "Independently re-read the pin at .ufo/waves/round-47/fetch/xdg-terminal-exec: read_cache/gen_hash/save_cache/print-content and command-v. Build bounded scratch cases for unreadable cache, no trailing newline, invalid 50-line boundary, line-49 terminator, multiline cached args, action, empty fields, cache path default and XTE_CACHE_ENABLED empty. Compare pin and frozen tool stdout/rc/cache state. No filesystem writes beyond your scratch."),
("RevC1Ls", "Attack exact `ls -LRl` hashing on the frozen C1 tool.", "Read the frozen counter and ExecLsEmu differential report, then run 500 independently seeded trees against `LC_ALL=C LANG=C ls -LRl` and the frozen tool's cache hash through the real pin; focus on multiple operands, numeric-owner padding, dangling symlinks, sibling symlink dirs, empty dirs, recent/future mtimes. Use scratch under your seat path, bounded. Report any mismatch with seed/tree reproduction."),
("RevC1Fixtures", "Attack the 204 frozen warm fixtures and class premises.", "Load every C1 fixture and verify each class label against its actual cold/warm oracle outputs, every record's state, `cold` and `expect`, and the cross-filesystem readdir premise. Mutate a cache file at the exact 49/50 line boundary and try `$ROOT` substitutions. Report counts and any drift/false premise; do not alter the fixtures."),
("RevC1Explain", "Attack explain's selected/path/cmd/cache and observed comparison.", "Using frozen C1 fixtures, build scratch cases where cache path/id/action/command differs, command includes an empty argument/newline, entry path is missing, `--print-content` fails, and observed capture is truncated or root-relative. Run actual counter and frozen tool. Does every bad explain control miss? Return exact counter output and case."),
("RevC2Counter", "Attack C2 counter clauses a-i and replay r.", "Run the frozen C2 counter on the lane's intended data candidate in a scratch clone; mutate each one of S340-S350 pin, digest, source ID, recheck, quote/range, entry step locator, receipt positive digest, negative rc, README row, held row, and absent-ground term. Each mutation must miss its declared clause. Also try an untrusted/relabelled receipt and an alternate pin with the same filename. Report matrix + potential false admission."),
("RevC2Entry", "Adversarially review XKB knowledge truth, scope and held-ground separation.", "Read the frozen C2 entry and every cited pin/receipt. For each numbered step, verify the claim from its locator; especially empty options vs NULL, XKB_DEFAULT_* with Hyprland `NO_FLAGS`, xkbcli env flags, generated evdev mapping, error severities, and include order. Find unsupported/wrong/out-of-province statements, quote evidence and state claim effect; never edit source tree."),
("RevRoutes", "Independent review of both claims' causal separability and weakest controls.", "Read both frozen claims/counters. Construct an entry-only positive control and a tool-only positive control in scratch; verify C2 can pass without C1 and C1 can pass without C2. Attack each target with the cheapest skip-work control. Report any predicate coupling, overclaim or hidden lowest-axis/quality-trend harm.")]:
    seat(n,"reviewer",target,task)

# 8 critics: attempt direct falsification.
for n, target, task in [
("CritC1OneByte", "Find a warm cache whose one-byte mutation exposes a C1 mismatch.", "Enumerate the frozen warm cases and test one-byte mutations of each cache line, including field 11 RS terminator, empty USEP fields, line 50 and trailing newline. Use the real pin and frozen tool in scratch; cite exact rc/stdout/state and counter verdict. If any incorrect tool passes, give the smallest added fixture."),
("CritC1Time", "Falsify cache hash date/time boundaries.", "Run real pin vs frozen tool with explicit file/dir mtimes at now, now-1s, now-six-months ±1s, future +1s, same-minute same-size edits, using controlled TZ. Confirm which are in contract vs declared OOC and whether fixtures hold same date strings in both variants. Output command, pin hash, tool hash and counter result."),
("CritC2Scope", "Falsify that the C2 source/entry is new and within mado.", "At frozen base, git-grep every C2 ground term and inspect held S318/S319 + PROVINCE. At candidate, identify any sentence re-claiming the r46 entry or any shokuknow/sibling scope. Verify sibling connector's report if available; document any contested boundary with paths/lines."),
("CritC2FalseClaim", "Try to falsify all C2 empirical XKB classifications.", "Run bounded host read-only xkbcli probes listed in the receipt: unknown layout/variant/rules, unknown option/model, multi-layout misalignment, custom include paths. Compare stdout/stderr/rc to the entry and counter replay. Never run pacman or mutate input; receipt device names must not be printed."),
("CritC2Pin", "Attack registry source-row anchors, recheck and tier.", "For every S340-S350 row, verify URL/ref, pin digest, anchor line and quote; determine whether S346's package-generated evdev has a sufficient provenance chain and whether S350 own-work points to a citable live receipt. Run sources-census on scratch registry; classify W04/E04 and any malformed row."),
("CritRouted", "Falsify closure of D1-D4, R3 and R4b.", "Read w1 reports and compare their concrete deliverables with the base bytes. Did the D1 conditional HOME behavior get measured and frozen? Does D3 include two-valid-candidate readdir fixtures? Does R3 marker fail both ways and preserve real findings? Does R4b append preserve the frozen r45 verdict? Does D4 range fix actually land append-only? Return per-item evidence and any blocker."),
("CritMistakes", "Attack the five proposed M48 mistakes/criteria for duplication or invalid evidence.", "Read ScrMistakes draft, QUALITY 1-95, and each check/receipt. Does each new criterion duplicate existing criteria? Does its check fail for the stated red input and pass only after the fix? Does M48-5's wave limit claim have a real command/enforcement, or is it only prose? Report reductions or failure evidence."),
("CritQualityTrend", "Adversarially assess C1/C2 and learning trend quality without trading axes.", "Assess whether C1 actually advances the operability surface despite curation coverage held at r47; whether C2 is new ground beyond r46; check all claims against a do-nothing counter, and any harm to held rows/index/quality. Distinguish self-reported evidence from peer evidence. Report which trend verdicts the data actually support.")]:
    seat(n,"critic",target,task)

# 6 mutation testers: mutate frozen instruments and actual artifacts.
for n, target, task in [
("MutC1Counter", "Mutate C1 frozen counter clauses and verify frozen controls kill them.", "Make one mutation per a/s/f/w/x/g/i/r clause in scratch copies only; score all 204 warm + 190 cold fixtures. Include always-accept warm, remove hash comparison, remove XTE_CACHE_ENABLED branch, skip line limit, ignore observed command, remove no-write tripwire. Record killed/surviving mutants and exact outputs."),
("MutC1Tool", "Mutation-test the warm-cache implementation against the frozen fixture suite.", "Mutate one behavior at a time in scratch: skip hash, trust cache, never use warm cache, break `command -v`, off-by-one line 50, ignore cached action/arg, lowercase desktop before hash, force cache=hit. Run counter for each. Any surviving realistic mutant names a fixture gap."),
("MutC2Counter", "Mutate C2 counter to find false-positive controls.", "One mutant per C2 clause and replay r: skip pin digest, allow branch URL, accept any quote, permit missing locator, do not compare replay digest, ignore held row changes, README row check always true, no ground-absent check. Run counter on each scratch tree and preserve per-mutant output."),
("MutC2Entry", "Mutation-test C2 row/entry claim evidence by changing one source fact.", "In scratch copies mutate quote, pin, numeric rc, rule mapping, include path order, and held S319 citation; score C2 counter. Then make a non-literal factual mutation the counter might not see (e.g. invert prose outcome while retaining evidence) and document the semantic checker gap."),
("MutC1ReadOnly", "Mutate C1 no-process/no-write boundary.", "Test controls that call `ls`, write a cache file, create a temp file, open a socket or invoke an absolute-path executable. Run the frozen counter's strace/tree checks on scratch. If an action is not observable by clause r or tree fingerprint, prove it with a harmless bounded control and name the needed clause."),
("MutC2Receipt", "Mutate/replay the xkbcli receipt and its expected digest.", "On scratch clones change only keymap digest, positive command argv, one negative rc, diagnostic code, version or entry line; run frozen C2 counter. Check replay actually binds bytes to output and never trusts a digest chosen by the mutated receipt. Report any mutation that admits.")]:
    seat(n,"mutation-tester",target,task)

# 4 scouts, 3 connectors, 3 sentinels, 2 additional reviewers/critics = 32 total.
for n,role,target,task in [
("ScoutFreezeBlobs","scout","Inventory every artifact needed in the freeze/data commits.","Compare w1 seat produced files vs claims/registration references; list exact paths, bytes and SHA256; identify any uncommitted path >1MiB that helper would skip, and any missing receipt. No writes outside your seat report."),
("ScoutCensus","scout","Independently verify source census before/after on candidate data.","Run frozen sources-census on the base and a scratch mirror with proposed rows/entry, recording both full output and exit code. Verify 11 columns, IDs, W04 warnings, W01/W03 and no E03/E04. Check lesson Gate's quote requirements per row."),
("ScoutConsiderthese","scout","Falsify the chosen consideration and assimilation dispositions.","Check considerthese proposal 6 status against base bytes and ScrConsider evidence; independently scan staged merge/mado package for XKB/terminal-cache theme and recompute §10 id/collision/quarantine counts. Report evidence for Assimilation none and the proposed criterion disposition."),
("ScoutMisroot","scout","Adversarial check of fleet-root misroot quarantine and scope.","Read the orchestrator notice and quarantine SHA256SUMS; confirm which file moved, hash equality against named path/report, and that no other fleet-root untracked files attributable to round 48 remain. Do not write/delete any fleet-root file."),
("ConnClaimOverlap","connector","Cross-claim and sibling pattern scan for data overlap.","Scan claim C1/C2, quality review and relevant sibling PROVINCE/SOURCES snippets for common evidence or ownership. Verify separability and whether terminal cache is a new executed surface while XKB compile is new sourced ground; write no production files."),
("ConnSourceLinks","connector","Find inconsistencies across C2 entry, SOURCES rows, README, Gate and receipt.","Crosswalk every source S340-S350 cited in entry to exactly one row, pin file/digest, Gate URL/quote, and README coverage ID. Report mismatched numbering, used-by, anchors, IDs, or coverage claim."),
("ConnMistakes","connector","Crosswalk each mined mistake to evidence, capture criterion and fix.","For M48-1..M48-5, check captured-by criteria and red/green receipts. Check proposal 6 criterion and any misroot/message-by-name incident handling. Name unlanded fix gaps and any double-counting."),
("SentHost","sentinel","Threat review host-side tools/commands used by C1/C2.","Check pin invocations all include print option and scratch XDG_CACHE_HOME; xkbcli uses only read-only verbs; no pacman install/query; no host writes/service/compositor changes. Identify accidental sensitive values and exact cleanup issues; class names only."),
("SentScratch","sentinel","Check every C1/C2 scratch writer's containment and bounds.","Review counter `--work`, c2 replay TMPDIR, w1/w2 seat scratch prompts and any unbounded loops/large writes. The 2026-10-25 rule requires /fast scratch, no /tmp, ≤1MB files, ≤2GB total and cleanup. Report actual hardcoded /tmp or missing bounds with path/line."),
("SentScope","sentinel","Check source/read-only and fleet write scope.","Verify no source checkout writes or campaign tools, and no seat notes/outputs in fleet root except quarantined tree.json notice. Inspect write-tree/diff receipts and quarantine. List exact scope concerns, never modify anything."),
("RevXkbIntent","reviewer","Reverse-check whether C2 explains actual host compile behavior without overclaim.","Inspect the pinned xkbcommon and xkeyboard-config semantics, compare xkbcli against Hyprland NO_FLAGS context, verify the entry explicitly limits compositor-side live claims and kb_file bypass. Report any unsupported mechanism or omitted failure condition."),
("RevQualityAdmission","reviewer","Review both frozen claim predicates as hostile closure verifier.","Using only committed bytes and local tools, independently reproduce both before/after counters on scratch clones, verify a positive control and a do-nothing control for each, verify no changed held axis/corpus rows, and state which evidence remains self-authored. Return a checklist, not an admission ruling."),
("CritContextDrift","critic","Attack wave dispatch compliance and model/scratch/safety instructions.","Check every w2 seat starts Godspeed directive bytes, names absolute lane paths, no model param, task roles through host table, pacman guard, read RULES, and seat-private scratch. Try validator refusal on spec (do not dispatch). Report any structural gap before L1 lands."),
("CritCounterTiming","critic","Falsify C1 cache state and timing assumptions in the frozen counter.","Test prime waiter determinism, cache file completion, HOME-unset pre-gate state, invalid cache truncation and 50-line behavior on the pinned shell. Verify variants and cold twins do not race or leak caches. Report any intermittent result across 3 runs."),
("CritFrontier","critic","Falsify the sources-census and lesson frontier step completeness.","Inspect row-Gate evidence for every newly added S id, re-open each quote in committed pin, inspect reject Gate rows and flip conditions, count lesson mistakes, verify census exit 0 and before/after outputs, and whether a round claim rests on an opened S row."),
("RevErrataR45","reviewer","Re-run R4b append proof and two negative controls.","Use ExecErrataR45's committed block and scripts after W1; append only in a private clone, run frozen r45 counter at before/after revisions, verify six locators, and ensure invalid wording misses. Report exact commands/results."),
("MutC2OneByte","mutation-tester","Try same-size quote/anchor mutations that may evade C2's instrument.","Mutate a quote to a true but unsupported quote, shift a locator to another in-range line, swap the receipt's diagnostic while keeping rc, and remove a statement but leave source row. Score counter; distinguish detected from semantic gaps."),
("MutRoutedR3","mutation-tester","Attack the synthetic marker gate patch proposed for R3.","If the marker patch/draft exists, run its selftest on base and marked/unmarked/planted-real controls in a private clone. Mutate marker registry/sidecar and confirm fail-closed; if not landable, state exact blocker and evidence; never write lane files."),
("ScoutQualityCriteria","scout","Audit proposed QUALITY 96-100 against current criteria and instrument outputs.","For each proposed criterion, identify nearest existing row and cite evidence that it is not duplicate. Re-run the exact red/green test on candidate bytes if feasible; report all unprovable proposals and any criterion that falsely passes."),
("ScoutEntryLocators","scout","Independent line/quote verification of the C2 entry.","Compute all pin locator ranges and quoted substrings from committed bytes after freeze; verify source lines and quote lengths, steps, held reference, and xkb receipt result. Report any cut/out-of-range locator."),
("CritSessionMarker","critic","Review R3 synthetic-material marker integration for ledger hazards.","Compare patch with the gate's registered criteria and all session-material sidecars; verify marker does not let forged real-looking data escape and excludes only marked synthetic fixtures. If cannot demonstrate, mark R3 open; do not widen claim."),
("CritC1LsEnv","critic","Check unsupported environment semantics in the Python ls model.","Test BLOCK_SIZE, POSIXLY_CORRECT, TIME_STYLE, QUOTING_STYLE, LS_COLORS, TZ, COLUMNS against model and real pin's `ls`; confirm the frozen contract rejects/says OOC when needed. Find edge where OOC isn't enforced but model silently returns wrong hash; report a counterexample or none with sweep output."),
("RevMisroot","reviewer","Independent signoff on the attributed misroot note.","Check quarantined fleet-root tree.json SHA256SUMS, seat report admits, and lane wave artifacts don't contain its bytes at fleet root. Provide exact hash/check output; no move/delete."),
("MutC2Replay","mutation-tester","Try replay predicate bypass via executable/path selection or environment.","Change PATH/xkbcli shim or XKB_CONFIG_ROOT under a controlled subprocess to see if clause r measures host's real pinned xkbcli or accepts a fake. Do not modify system environment or install; use a scratch wrapper and name the residual."),
("ScoutControls","scout","Count actual frozen controls and their outcomes across both claims.","Inventory the w1 C1/C2 controls and controls.txt outputs. Compare against registration's mandatory controls list; identify controls not run, survivors, or report mismatch. Cite output paths and SHA256."),
("CritDataCompleteness","critic","Find omissions among 204 warm fixture classes and 11 source rows.","Independently enumerate fixture classes and source rows, compare each requested axis-move and routed item to actual data. For any missing class/source, propose exact item and show why existing clauses don't catch it.")]:
    seat(n,role,target,task)
for item in items:
    if item["name"] in {
        "RevC1Counter", "RevC1Cache", "RevC1Ls", "RevC1Fixtures", "RevC1Explain", "RevC2Counter",
        "CritC1OneByte", "CritC1Time", "CritC2Scope", "CritC2FalseClaim", "CritC2Pin", "CritRouted",
        "CritMistakes", "CritQualityTrend", "MutC1Counter", "MutC1Tool", "MutC2Counter", "MutC2Entry",
        "MutC1ReadOnly", "MutC2Receipt", "MutC2OneByte", "ScoutFreezeBlobs", "ScoutCensus",
    }:
        item["role"] = "executor"
for item in items:
    if item["name"] in {"ScoutConsiderthese", "ScoutQualityCriteria", "ScoutEntryLocators", "ScoutControls"}:
        item["role"] = "critic"
assert len(items)==48,len(items)
print(len(items),dict(collections.Counter(x['role'] for x in items)))
spec={"wave":"w2","context":CONTEXT,"reportDir":".ufo/waves/round-48/w2","items":items}
with open(os.path.join(W,"w2-spec.json"),"w") as f: json.dump(spec,f,indent=1,ensure_ascii=False); f.write("\n")
